for file in mssparkutils.fs.ls(file_path):
    if file.name == '_SUCCESS':
        mssparkutils.fs.rm(file.path)
        #print(file.path)
    else:
        newFilePath = file_path + "/jsonAccertamenti.json"
        mssparkutils.fs.cp(file.path, newFilePath,False)
        mssparkutils.fs.rm(file.path)
